    'team.grace.role': 'Co-Founder',
    'team.grace.bio': 'One of the four East Aurora High School students who recognized the urgent need for organ donation reform in New York State.',
    'team.sage.role': 'Co-Founder',
    'team.sage.bio': 'Helped build YCOD from a school club initiative into a multinational movement with over 3,000 members.',

    // PARTNER descriptions
    'partner.waitlist_zero': 'Founded by living kidney donors, devoted to ending the organ transplant waiting list through policy reform and public education.',
    'partner.one8fifty': 'Free texting registration system — text "register" to 57838 to join the organ donor registry instantly.',
    'partner.chris_klug': 'Founded by Olympic bronze medalist and organ transplant recipient Chris Klug, promoting organ donation and healthy post-transplant lifestyles.',
    'partner.red_cross': 'Spanning 27 counties and 3 chapters across Western New York, supporting communities through blood drives, disaster relief, and health programs.',
    'partner.council_churches': 'Comprised of 8 partner denominations, supporting organ donation advocacy through faith-based communities across New York State.',

    // INITIATIVE data
    'initiative.optout.title': 'Opt-Out Organ Donation',
    'initiative.optout.summary': 'Change the default at the DMV from opt-in to opt-out for organ donation.',
    'initiative.optout.desc': "Our flagship legislative campaign aims to change New York's DMV default from opt-in to opt-out for organ donation registration. This behavioral-economics-driven approach has been proven to dramatically increase donor registration rates in countries like Spain, the UK, Austria, and France. We drafted and proposed Bill A07954 in 2019 with an updated version in 2021.",
    'initiative.nonpartisan.title': 'Nonpartisan Politics',
    'initiative.nonpartisan.summary': 'Keeping the message open to everyone regardless of political beliefs.',
    'initiative.nonpartisan.desc': 'Organ donation transcends political divides. Our nonpartisan approach ensures that everyone — regardless of political affiliation — can join in supporting life-saving legislation. When it comes to saving lives, we believe New Yorkers can put their differences aside.',
    'initiative.education.title': 'Youth Education',
    'initiative.education.summary': 'Including the next generation through school curriculum advocacy.',
    'initiative.education.desc': "We advocate for organ donation education in school curricula and support youth leadership programs like Donate Life Clubs. By empowering young people with knowledge, we're building a generation of informed advocates who understand the importance of organ donation.",
    'initiative.health.title': 'Healthier Communities',
    'initiative.health.summary': 'Encouraging communities to support those in need of transplants.',
    'initiative.health.desc': 'We work to build healthier communities by encouraging families to have conversations about organ donation. 66% of living organ donors give to a family member — this is deeply personal for everyone. We support community engagement initiatives that bring people together around this life-saving cause.',
    'initiative.info.title': 'Informational Campaign',
    'initiative.info.summary': 'Public awareness and education about organ donation facts.',
    'initiative.info.desc': "Through media campaigns, social media outreach, and partnerships with organizations like ONE8FIFTY, we spread the facts about organ donation. 90% of US adults support organ donation, but only 60% are registered — we're closing that gap through education and awareness.",

    // FACTS data
    'fact.0.title': 'Lives Lost Every Day',
    'fact.0.desc': "17 people die every single day waiting for an organ transplant. That's one person every 85 minutes — and every one of them had someone who loved them.",
    'fact.1.title': 'People on the Waitlist Right Now',
    'fact.1.desc': 'Over 103,000 Americans are waiting for a life-saving organ transplant at this very moment. The list grows faster than donors can keep up.',
    'fact.2.title': 'New Yorkers Waiting',
    'fact.2.desc': 'Roughly 8,000 of your neighbors, coworkers, and classmates across New York State are on the transplant waitlist. This is local.',
    'fact.3.title': 'One Donor, Many Lives',
    'fact.3.desc': 'A single organ donor can save up to 8 lives through transplants — and heal 75 or more people through tissue donation. One decision, dozens of futures.',
    'fact.4.title': 'The Support-Action Gap',
    'fact.4.desc': '90% of US adults say they support organ donation — but only about 60% are actually registered. That 30-point gap costs lives. A simple default change could close it.',
    'fact.5.title': "New York's Registration Problem",
    'fact.5.desc': "New York has historically ranked near the bottom nationally for donor registration. The rate has been climbing — crossing 50% in late 2024 — but there's still a long way to go.",
    'fact.6.title': 'Countries With Opt-Out Systems',
    'fact.6.desc': "Over 30 countries — including Spain, the UK, France, Austria, the Netherlands, Argentina, Chile, and Singapore — already use opt-out organ donation. It's not radical. It's the global standard.",
    'fact.7.title': 'The Kidney Crisis',
    'fact.7.desc': '85% of people on the national transplant waitlist need a kidney. Kidneys are by far the most needed organ — and the wait can stretch five years or more.',
    'fact.8.title': 'Living Donors Give to Family',
    'fact.8.desc': "66% of living organ donors give to a family member. When you register, you're not helping a stranger in the abstract — you may be protecting someone you love.",
    'fact.9.title': 'Religions That Oppose Donation',
    'fact.9.desc': 'Zero. No major world religion — Christian, Jewish, Muslim, Hindu, Buddhist, Sikh, or otherwise — opposes organ donation after death. Faith leaders across the board call it an act of compassion.',
    'fact.10.title': 'Youth Are Ready to Act',
    'fact.10.desc': 'Young Americans are more civically engaged than any generation in 50 years. Over 80% of Gen Z say they support organ donation — they just need a clear path to register.',
    'fact.11.title': 'Never Too Old to Save a Life',
    'fact.11.desc': "Cecil Lockhart became an organ donor at age 95 — the oldest on record. There is no age limit. If you have a healthy organ, you can be someone's miracle.",

