    // Myth vs Fact (MythVsFact)
    'myth.0.myth': 'Doctors won\'t try as hard to save me if I\'m a registered donor.',
    'myth.0.fact': 'Your medical team\'s only job is to save YOUR life. Organ donation is only considered after all life-saving measures have been exhausted and death is declared by a completely separate team.',
    'myth.1.myth': 'I\'m too old to be an organ donor.',
    'myth.1.fact': 'There is no age limit for organ donation. Cecil Lockhart donated organs at age 95. Medical suitability is determined at the time of death, not by your birthday.',
    'myth.2.myth': 'My religion doesn\'t allow organ donation.',
    'myth.2.fact': 'No major world religion opposes organ donation. Christianity, Judaism, Islam, Hinduism, Buddhism, and Sikhism all support it as an act of compassion and generosity.',
    'myth.3.myth': 'If I donate, my body won\'t be suitable for an open-casket funeral.',
    'myth.3.fact': 'Organ and tissue recovery is performed by skilled surgeons in a sterile operating room. The body is treated with dignity and respect, and an open-casket funeral is absolutely possible.',
    'myth.4.myth': 'Rich or famous people get organs faster.',
    'myth.4.fact': 'The organ allocation system (managed by UNOS) is based on medical urgency, blood type, time on the waitlist, and geographic proximity — not wealth, fame, or social status.',
    'myth.5.myth': 'Organ donation costs money for the donor\'s family.',
    'myth.5.fact': 'There is zero cost to the donor\'s family for organ donation. All medical costs related to donation are covered by the organ procurement organization or the recipient\'s insurance.',

    // Timeline events (InteractiveTimeline)
    'timeline.founded.title': 'YCOD is Founded',
    'timeline.founded.desc': 'After Evan\'s family member needs a kidney transplant, four East Aurora High School students found the Youth Coalition for Organ Donation.',
    'timeline.founded.detail': 'What began as a personal cause — Evan\'s family member needed a kidney transplant — became a mission. Four East Aurora High School students decided they wouldn\'t just wait for change. They\'d make it.',
    'timeline.donate_life.title': 'Joined Donate Life Club',
    'timeline.donate_life.desc': 'The founders join their school\'s Donate Life Club and discover that New York has one of the lowest donor registration rates in the country at just 37%.',
    'timeline.donate_life.detail': 'The founders were shocked to discover that New York\'s 37% registration rate was among the lowest in the nation. They realized the problem wasn\'t that people opposed donation — it was that the system made it too easy to say nothing.',
    'timeline.growing.title': 'Growing the Movement',
    'timeline.growing.desc': 'YCOD begins building a coalition of young people across New York State, reaching hundreds of supporters.',
    'timeline.growing.detail': 'Word spread beyond East Aurora. Students, teachers, and community members across New York State started joining. YCOD went from a school club to a statewide coalition in just one year.',
    'timeline.bill_drafted.title': 'Bill A07954 Drafted',
    'timeline.bill_drafted.desc': 'YCOD drafts and proposes actual legislation — Bill A07954 — to change the DMV default from opt-in to opt-out for organ donation.',
    'timeline.bill_drafted.detail': 'Most student groups write letters. YCOD wrote actual legislation. Bill A07954 proposed changing the DMV default from opt-in to opt-out — a simple behavioral change backed by decades of research.',
    'timeline.partnerships.title': 'Partnership Expansion',
    'timeline.partnerships.desc': 'Key partnerships formed with WaitList Zero, ONE8FIFTY, Chris Klug Foundation, American Red Cross WNY, and NY State Council of Churches.',
    'timeline.partnerships.detail': 'YCOD partnered with WaitList Zero, ONE8FIFTY, the Chris Klug Foundation, the American Red Cross WNY, and the NY State Council of Churches — building a coalition that spans healthcare, faith, and sports.',
    'timeline.red_cross.title': 'Red Cross Nomination',
    'timeline.red_cross.desc': 'YCOD is nominated for the American Red Cross Real Heroes Education Award. Updated draft legislation is prepared.',
    'timeline.red_cross.detail': 'Recognition from the American Red Cross validated what the team already knew: young people can drive real policy change. The nomination brought national attention to YCOD\'s legislative approach.',
    'timeline.tedx.title': 'TEDx Talk',
    'timeline.tedx.desc': 'Evan Roden delivers a TEDx talk on youth political engagement and organ donation, reaching thousands of viewers.',
    'timeline.tedx.detail': 'Evan took the stage at TEDx to make the case that young people aren\'t apolitical — they\'re more engaged than ever. The talk connected organ donation advocacy to the broader story of youth civic engagement.',
    'timeline.members_3000.title': '3,000+ Members',
    'timeline.members_3000.desc': 'The movement grows to over 3,000 members from across the United States and around the world.',
    'timeline.members_3000.detail': 'From four students in one school to over 3,000 members spanning multiple countries. YCOD proved that organ donation advocacy resonates across borders, cultures, and generations.',
    'timeline.ny_50.title': 'NY Crosses 50%',
    'timeline.ny_50.desc': 'A milestone moment: New York State crosses 50% organ donor registration for the first time in October 2024.',
    'timeline.ny_50.detail': 'After years of advocacy, New York finally crossed the 50% registration threshold. It\'s progress — but with states like Alaska at 90%+, there\'s still work to do.',

