    // Letter Generator template
    'letter.body': '尊敬的[代表姓名]，\n\n我叫{name}，是来自{zip}的选民，写信敦促您支持纽约州的器官捐献退出制度立法。\n\n目前，超过8,000名纽约人正在等待挽救生命的器官移植。美国每天有17人在等待器官的过程中死亡——每85分钟就有一人。尽管90%的美国人支持器官捐献，但只有约50%的纽约人注册为捐献者。\n\n解决方案简单且经过验证：将DMV的默认设置从选择加入改为选择退出。超过30个国家——包括西班牙、英国、法国和奥地利——已经使用这一系统，他们始终实现80-90%的注册率。没有人被迫捐献；任何人随时可以退出。唯一改变的是默认设置。\n\n{story}这不是党派问题。拯救生命超越政治分歧。我请求您支持在DMV实施器官捐献退出注册系统的立法，类似于法案A07954。\n\n感谢您的时间和对社区的服务。\n\n此致，\n{name}\n{zip}',

