    'initiative.optout.title': '器官捐献退出制度',
    'initiative.optout.summary': '将DMV的器官捐献默认设置从选择加入改为选择退出。',
    'initiative.optout.desc': '我们的旗舰立法运动旨在将纽约DMV的器官捐献注册默认设置从选择加入改为选择退出。这种基于行为经济学的方法已被证明能在西班牙、英国、奥地利和法国等国家大幅提高捐献者注册率。我们在2019年起草并提出了法案A07954，并在2021年更新了版本。',
    'initiative.nonpartisan.title': '无党派政治',
    'initiative.nonpartisan.summary': '无论政治信仰如何，向所有人开放信息。',
    'initiative.nonpartisan.desc': '器官捐献超越政治分歧。我们的无党派方法确保每个人——无论政治立场如何——都可以加入支持挽救生命的立法。在拯救生命方面，我们相信纽约人可以放下分歧。',
