    'initiative.education.desc': '我们倡导在学校课程中加入器官捐献教育，支持青年领导力项目如Donate Life社团。通过赋予年轻人知识，我们正在培养一代了解器官捐献重要性的知情倡导者。',
    'initiative.health.title': '更健康的社区',
    'initiative.health.summary': '鼓励社区支持需要移植的人。',
    'initiative.health.desc': '我们致力于通过鼓励家庭讨论器官捐献来建设更健康的社区。66%的活体器官捐献者捐给家庭成员——这对每个人都是非常个人化的。我们支持将人们团结在这一挽救生命事业周围的社区参与倡议。',
    'initiative.info.title': '信息宣传活动',
    'initiative.info.summary': '关于器官捐献事实的公众认知和教育。',
    'initiative.info.desc': '通过媒体宣传、社交媒体推广以及与ONE8FIFTY等组织的合作，我们传播器官捐献的事实。90%的美国成年人支持器官捐献，但只有60%已注册——我们正在通过教育和认知来缩小这一差距。',

    // FACTS data
    'fact.0.title': '每天失去的生命',
    'fact.0.desc': '每天有17人在等待器官移植的过程中死亡。每85分钟就有一人——他们每个人都有爱他们的人。',
    'fact.1.title': '现在等待名单上的人',
    'fact.1.desc': '超过103,000名美国人此刻正在等待挽救生命的器官移植。名单增长的速度超过了捐献者的步伐。',
    'fact.2.title': '等待中的纽约人',
    'fact.2.desc': '纽约州约有8,000名您的邻居、同事和同学在移植等待名单上。这很本地化。',
    'fact.3.title': '一位捐献者，多条生命',
    'fact.3.desc': '一位器官捐献者可以通过移植拯救多达8条生命——并通过组织捐献帮助75人或更多人。一个决定，数十个未来。',
    'fact.4.title': '支持与行动差距',
    'fact.4.desc': '90%的美国成年人表示支持器官捐献——但只有约60%实际注册了。这30个百分点的差距夺走了生命。简单的默认改变就能弥合它。',
    'fact.5.title': '纽约的注册问题',
    'fact.5.desc': '纽约州在全国捐献者注册率中历来排名靠后。该比率一直在攀升——在2024年底超过了50%——但仍有很长的路要走。',
    'fact.6.title': '拥有退出制度的国家',
    'fact.6.desc': '超过30个国家——包括西班牙、英国、法国、奥地利、荷兰、阿根廷、智利和新加坡——已经使用器官捐献退出制度。这不是激进的做法。这是全球标准。',
    'fact.7.title': '肾脏危机',
    'fact.7.desc': '全国移植等待名单上85%的人需要肾脏。肾脏是迄今为止最需要的器官——等待可能长达五年或更长。',
    'fact.8.title': '活体捐献者捐给家人',
    'fact.8.desc': '66%的活体器官捐献者捐给家庭成员。当您注册时，您不是在抽象地帮助陌生人——您可能在保护您爱的人。',
    'fact.9.title': '反对捐献的宗教',
    'fact.9.desc': '零。没有任何主要世界宗教——基督教、犹太教、伊斯兰教、印度教、佛教、锡克教或其他——反对死后器官捐献。各界信仰领袖一致称之为慈悲之举。',
    'fact.10.title': '青年准备行动',
    'fact.10.desc': '美国年轻人是50年来参与公民事务最积极的一代。超过80%的Z世代表示支持器官捐献——他们只需要一条清晰的注册途径。',
    'fact.11.title': '拯救生命永远不嫌老',
    'fact.11.desc': 'Cecil Lockhart在95岁时成为器官捐献者——这是有记录以来最年长的。没有年龄限制。如果您有健康的器官，您就可以成为某人的奇迹。',

