    // Myth vs Fact (MythVsFact)
    'myth.0.myth': '如果我是注册捐献者，医生就不会全力抢救我。',
    'myth.0.fact': '你的医疗团队唯一的职责就是拯救你的生命。只有在所有抢救措施都已用尽、并由完全独立的团队宣布死亡后，才会考虑器官捐献。',
    'myth.1.myth': '我年纪太大了，不能捐献器官。',
    'myth.1.fact': '器官捐献没有年龄限制。塞西尔·洛克哈特在95岁时捐献了器官。医学适合性是在死亡时确定的，而不是由你的生日决定。',
    'myth.2.myth': '我的宗教不允许器官捐献。',
    'myth.2.fact': '没有任何主要宗教反对器官捐献。基督教、犹太教、伊斯兰教、印度教、佛教和锡克教都支持将其作为慈悲和慷慨的行为。',
    'myth.3.myth': '如果我捐献器官，我的遗体将无法进行开棺葬礼。',
    'myth.3.fact': '器官和组织的获取由技术娴熟的外科医生在无菌手术室中进行。遗体会得到尊严和尊重的对待，开棺葬礼完全可以进行。',
    'myth.4.myth': '富人或名人能更快获得器官。',
    'myth.4.fact': '器官分配系统（由UNOS管理）基于医疗紧急程度、血型、等待名单上的时间和地理距离——而不是财富、名望或社会地位。',
    'myth.5.myth': '器官捐献会给捐献者家庭带来费用。',
    'myth.5.fact': '器官捐献对捐献者家庭完全免费。所有与捐献相关的医疗费用由器官获取组织或受者的保险承担。',

