    'timeline.partnerships.detail': 'YCOD与WaitList Zero、ONE8FIFTY、Chris Klug基金会、美国红十字会西纽约分会和纽约州教会理事会建立了合作——构建了一个横跨医疗、信仰和体育的联盟。',
