    'faq.subtitle': '关于器官捐献、退出制度以及如何帮助拯救生命，您需要了解的一切。',
    'faq.expand_all': '展开全部',
    'faq.collapse_all': '收起全部',
    'faq.category_label': '类别 {num}',
    'faq.cta_title': '还有疑问？',
    'faq.cta_subtitle': '联系我们的团队或浏览我们的资源，获取更多关于器官捐献的信息。',
