    'home.testimonials_subtitle': '听听正在做出改变的成员、捐献者和支持者的心声。',
    'home.testimonial.0.quote': '加入YCOD让我有机会将悲痛转化为行动。我的阿姨在等待肾脏移植的过程中去世了。没有家庭应该经历这些。',
