    'home.testimonial.0.role': 'YCOD成员，布鲁克林',
    'home.testimonial.1.quote': '作为一名生物老师，我每年都把器官捐献纳入课程。YCOD的资源使这变得简单，学生们总是很投入。',
    'home.testimonial.1.name': 'Mr. David Chen',
    'home.testimonial.1.role': '教育工作者，锡拉丘兹',
    'home.testimonial.2.quote': '我通过YCOD的短信系统注册为捐献者。只用了30秒。如果这么简单，就没有理由不做。',
    'home.testimonial.2.name': 'Jessica R.',
