    // =============================================
    // New Facts (indices 12-19)
    // =============================================
    'fact.12.title': '平均等待时间',
    'fact.12.desc': '在美国，肾脏移植的平均等待时间为3至5年。对于一些患者，等待时间更长——许多人在器官可用之前就已去世。',
    'fact.13.title': '西班牙的世界领先比率',
    'fact.13.desc': '西班牙拥有全球最高的器官捐献率，每百万人口49位捐献者。他们于1979年采用的退出制度是其他国家现在效仿的黄金标准。',
    'fact.14.title': '活体捐献者拯救生命',
    'fact.14.desc': '美国每年有超过6,000例活体器官捐献——主要是肾脏。您只需要一个肾脏就能过健康的生活，而且活体捐献的肾脏比遗体捐献的肾脏存活时间更长。',
    'fact.15.title': '肾脏疾病的代价',
    'fact.15.desc': '治疗肾衰竭每年耗费美国医疗系统超过500亿美元。一次肾脏移植在五年内可节省约30万美元的透析费用——并给予患者更好的生活。',
    'fact.16.title': '注册缺口',
    'fact.16.desc': '美国每年进行约28,000例器官移植——但超过100,000人仍在等待名单上。供需之间的缺口每年夺走数千条生命。',
    'fact.17.title': '第一百万例移植',
    'fact.17.desc': '美国第一百万例器官移植于2012年9月完成。此后，又有数十万条生命被挽救——但等待名单仍在持续增长。',
    'fact.18.title': '器官获取时间窗',
    'fact.18.desc': '死亡后，器官必须在数小时内获取和移植。心脏必须在4-6小时内移植，肺在6-8小时内，肾脏在24-36小时内。',
    'fact.19.title': '少数族裔健康差异',
    'fact.19.desc': '非裔和拉丁裔美国人占移植等待名单的60%以上，但在注册捐献者中所占比例较小。缩小这一差距需要具有文化敏感性的宣传和公平的获取途径。',

    // =============================================
    // New Quiz Questions (indices 5-9)
    // =============================================
    'quiz.5.q': '哪种器官最常被移植？',
    'quiz.5.a': '心脏',
    'quiz.5.b': '肾脏',
    'quiz.5.c': '肝脏',
    'quiz.5.d': '肺',
    'quiz.5.explain': '肾脏是迄今为止最常被移植的器官。等待名单上约85%的人需要肾脏，美国每年进行超过25,000例肾脏移植。',
    'quiz.6.q': '哪个国家的器官捐献率全球最高？',
    'quiz.6.a': '美国',
    'quiz.6.b': '西班牙',
    'quiz.6.c': '法国',
    'quiz.6.d': '日本',
    'quiz.6.explain': '西班牙拥有全球最高的器官捐献率，每百万人口49位捐献者。他们的退出制度加上卓越的移植协调，使其成为全球黄金标准。',
    'quiz.7.q': '注册为器官捐献者有最低年龄要求吗？',
    'quiz.7.a': '必须18岁以上',
    'quiz.7.b': '必须21岁以上',
    'quiz.7.c': '任何年龄均可，需父母同意',
    'quiz.7.d': '必须16岁以上',
    'quiz.7.explain': '在大多数州，任何人都可以在父母同意下注册为器官捐献者。18岁以下的人可以表达捐献意愿，其父母可以授权。',
    'quiz.8.q': '捐献的肾脏在体外可以存活多长时间？',
    'quiz.8.a': '4-6小时',
    'quiz.8.b': '12-18小时',
    'quiz.8.c': '24-36小时',
    'quiz.8.d': '48-72小时',
    'quiz.8.explain': '捐献的肾脏在妥善保存的情况下可以在体外存活24-36小时。心脏和肺的时间窗口要短得多——仅4-8小时。',
    'quiz.9.q': '活体器官捐献者中有多少比例捐给家人？',
    'quiz.9.a': '约25%',
    'quiz.9.b': '约45%',
    'quiz.9.c': '约66%',
    'quiz.9.d': '约85%',
