    'quiz.1.explain': 'Un donante de órganos puede salvar hasta 8 vidas a través de trasplantes y curar a 75 o más a través de donación de tejidos. Una persona, docenas de futuros.',
    'quiz.2.q': '¿Qué porcentaje de adultos estadounidenses apoyan la donación de órganos?',
