    // Myth vs Fact (MythVsFact)
    'myth.0.myth': 'Los médicos no se esforzarán tanto en salvarme si soy donante registrado.',
    'myth.0.fact': 'El único trabajo de tu equipo médico es salvar TU vida. La donación de órganos solo se considera después de que se hayan agotado todas las medidas para salvar la vida y la muerte sea declarada por un equipo completamente separado.',
    'myth.1.myth': 'Soy demasiado mayor para ser donante de órganos.',
    'myth.1.fact': 'No hay límite de edad para la donación de órganos. Cecil Lockhart donó órganos a los 95 años. La idoneidad médica se determina en el momento de la muerte, no por tu fecha de nacimiento.',
    'myth.2.myth': 'Mi religión no permite la donación de órganos.',
    'myth.2.fact': 'Ninguna religión importante del mundo se opone a la donación de órganos. El cristianismo, el judaísmo, el islam, el hinduismo, el budismo y el sijismo la apoyan como un acto de compasión y generosidad.',
    'myth.3.myth': 'Si dono, mi cuerpo no será adecuado para un funeral con ataúd abierto.',
    'myth.3.fact': 'La recuperación de órganos y tejidos la realizan cirujanos especializados en un quirófano estéril. El cuerpo es tratado con dignidad y respeto, y un funeral con ataúd abierto es absolutamente posible.',
    'myth.4.myth': 'Las personas ricas o famosas obtienen órganos más rápido.',
    'myth.4.fact': 'El sistema de asignación de órganos (gestionado por UNOS) se basa en la urgencia médica, el tipo de sangre, el tiempo en la lista de espera y la proximidad geográfica, no en la riqueza, la fama o el estatus social.',
    'myth.5.myth': 'La donación de órganos cuesta dinero a la familia del donante.',
    'myth.5.fact': 'La donación de órganos no tiene ningún costo para la familia del donante. Todos los costos médicos relacionados con la donación son cubiertos por la organización de obtención de órganos o el seguro del receptor.',

    // Timeline events (InteractiveTimeline)
    'timeline.founded.title': 'Se funda YCOD',
    'timeline.founded.desc': 'Después de que un familiar de Evan necesita un trasplante de riñón, cuatro estudiantes de East Aurora High School fundan la Coalición Juvenil para la Donación de Órganos.',
    'timeline.founded.detail': 'Lo que comenzó como una causa personal — un familiar de Evan necesitaba un trasplante de riñón — se convirtió en una misión. Cuatro estudiantes de East Aurora High School decidieron que no solo esperarían el cambio. Lo crearían.',
    'timeline.donate_life.title': 'Se unen al club Donate Life',
    'timeline.donate_life.desc': 'Los fundadores se unen al club Donate Life de su escuela y descubren que Nueva York tiene una de las tasas de registro de donantes más bajas del país, con solo el 37%.',
    'timeline.donate_life.detail': 'Los fundadores se sorprendieron al descubrir que la tasa de registro del 37% de Nueva York estaba entre las más bajas del país. Se dieron cuenta de que el problema no era que la gente se opusiera a la donación, sino que el sistema hacía demasiado fácil no decir nada.',
    'timeline.growing.title': 'Crecimiento del movimiento',
    'timeline.growing.desc': 'YCOD comienza a construir una coalición de jóvenes en todo el estado de Nueva York, alcanzando a cientos de simpatizantes.',
    'timeline.growing.detail': 'La noticia se extendió más allá de East Aurora. Estudiantes, profesores y miembros de la comunidad de todo el estado de Nueva York comenzaron a unirse. YCOD pasó de ser un club escolar a una coalición estatal en solo un año.',
    'timeline.bill_drafted.title': 'Proyecto de ley A07954',
    'timeline.bill_drafted.desc': 'YCOD redacta y propone legislación real — el proyecto de ley A07954 — para cambiar el valor predeterminado del DMV de inclusión voluntaria a exclusión voluntaria para la donación de órganos.',
    'timeline.bill_drafted.detail': 'La mayoría de los grupos estudiantiles escriben cartas. YCOD escribió legislación real. El proyecto de ley A07954 proponía cambiar el valor predeterminado del DMV de inclusión a exclusión voluntaria — un simple cambio de comportamiento respaldado por décadas de investigación.',
    'timeline.partnerships.title': 'Expansión de alianzas',
    'timeline.partnerships.desc': 'Se forman alianzas clave con WaitList Zero, ONE8FIFTY, la Fundación Chris Klug, la Cruz Roja Americana de WNY y el Consejo de Iglesias del Estado de Nueva York.',
    'timeline.partnerships.detail': 'YCOD se asoció con WaitList Zero, ONE8FIFTY, la Fundación Chris Klug, la Cruz Roja Americana de WNY y el Consejo de Iglesias del Estado de Nueva York — construyendo una coalición que abarca salud, fe y deporte.',
    'timeline.red_cross.title': 'Nominación de la Cruz Roja',
    'timeline.red_cross.desc': 'YCOD es nominado para el Premio de Educación Héroes Reales de la Cruz Roja Americana. Se prepara legislación actualizada.',
    'timeline.red_cross.detail': 'El reconocimiento de la Cruz Roja Americana validó lo que el equipo ya sabía: los jóvenes pueden impulsar cambios reales en las políticas. La nominación atrajo atención nacional al enfoque legislativo de YCOD.',
    'timeline.tedx.title': 'Charla TEDx',
    'timeline.tedx.desc': 'Evan Roden presenta una charla TEDx sobre participación política juvenil y donación de órganos, alcanzando a miles de espectadores.',
    'timeline.tedx.detail': 'Evan subió al escenario de TEDx para argumentar que los jóvenes no son apolíticos — están más comprometidos que nunca. La charla conectó la defensa de la donación de órganos con la historia más amplia de la participación cívica juvenil.',
    'timeline.members_3000.title': '3,000+ miembros',
    'timeline.members_3000.desc': 'El movimiento crece a más de 3,000 miembros de todo Estados Unidos y el mundo.',
    'timeline.members_3000.detail': 'De cuatro estudiantes en una escuela a más de 3,000 miembros en múltiples países. YCOD demostró que la defensa de la donación de órganos resuena a través de fronteras, culturas y generaciones.',
    'timeline.ny_50.title': 'NY supera el 50%',
    'timeline.ny_50.desc': 'Un momento histórico: el estado de Nueva York supera el 50% de registro de donantes de órganos por primera vez en octubre de 2024.',
    'timeline.ny_50.detail': 'Después de años de defensa, Nueva York finalmente cruzó el umbral del 50% de registro. Es un avance — pero con estados como Alaska por encima del 90%, aún queda trabajo por hacer.',


