    'home.news.0.title': 'Cómo YCOD Está Liderando un Movimiento Juvenil por la Reforma de la Donación de Órganos',
    'home.news.1.title': 'Mes Nacional de Donar Vida: Por Qué Abril Importa para la Donación de Órganos',
    'home.news.2.title': 'La Donación de Órganos en Vida Alcanza Cifras Récord en Estados Unidos',
