    'bill.compare_feature': 'Característica',
    'bill.compare_optin': 'Inclusión (Actual)',
    'bill.compare_optout': 'Exclusión (Propuesto)',
    'bill.compare.default.label': 'Estado Predeterminado',
    'bill.compare.default.optin': 'No eres donante a menos que te registres',
