    'quiz.1.c': "Jusqu'à 8 vies",
    'quiz.1.d': "Jusqu'à 15 vies",
    'quiz.1.explain': "Un donneur d'organes peut sauver jusqu'à 8 vies par des greffes et guérir 75 personnes ou plus par le don de tissus. Une personne, des dizaines d'avenirs.",
    'quiz.2.q': "Quel pourcentage d'adultes américains soutiennent le don d'organes ?",
