    // Myth vs Fact (MythVsFact)
    'myth.0.myth': 'Les médecins ne feront pas autant d\'efforts pour me sauver si je suis donneur inscrit.',
    'myth.0.fact': 'Le seul travail de votre équipe médicale est de sauver VOTRE vie. Le don d\'organes n\'est envisagé qu\'après l\'épuisement de toutes les mesures de sauvetage et la déclaration du décès par une équipe complètement distincte.',
    'myth.1.myth': 'Je suis trop vieux pour être donneur d\'organes.',
    'myth.1.fact': 'Il n\'y a pas de limite d\'âge pour le don d\'organes. Cecil Lockhart a fait don de ses organes à 95 ans. L\'aptitude médicale est déterminée au moment du décès, pas par votre date de naissance.',
    'myth.2.myth': 'Ma religion n\'autorise pas le don d\'organes.',
    'myth.2.fact': 'Aucune grande religion mondiale ne s\'oppose au don d\'organes. Le christianisme, le judaïsme, l\'islam, l\'hindouisme, le bouddhisme et le sikhisme le soutiennent tous comme un acte de compassion et de générosité.',
    'myth.3.myth': 'Si je fais un don, mon corps ne sera pas présentable pour des funérailles à cercueil ouvert.',
    'myth.3.fact': 'Le prélèvement d\'organes et de tissus est effectué par des chirurgiens qualifiés dans un bloc opératoire stérile. Le corps est traité avec dignité et respect, et des funérailles à cercueil ouvert sont tout à fait possibles.',
    'myth.4.myth': 'Les personnes riches ou célèbres obtiennent des organes plus rapidement.',
    'myth.4.fact': 'Le système d\'attribution des organes (géré par l\'UNOS) est basé sur l\'urgence médicale, le groupe sanguin, le temps sur la liste d\'attente et la proximité géographique — pas sur la richesse, la célébrité ou le statut social.',
    'myth.5.myth': 'Le don d\'organes coûte de l\'argent à la famille du donneur.',
    'myth.5.fact': 'Le don d\'organes n\'entraîne aucun coût pour la famille du donneur. Tous les frais médicaux liés au don sont pris en charge par l\'organisme de prélèvement d\'organes ou l\'assurance du receveur.',

    // Timeline events (InteractiveTimeline)
    'timeline.founded.title': 'Fondation de YCOD',
    'timeline.founded.desc': 'Après qu\'un membre de la famille d\'Evan a besoin d\'une greffe de rein, quatre élèves du lycée East Aurora fondent la Coalition des Jeunes pour le Don d\'Organes.',
    'timeline.founded.detail': 'Ce qui a commencé comme une cause personnelle — un membre de la famille d\'Evan avait besoin d\'une greffe de rein — est devenu une mission. Quatre élèves du lycée East Aurora ont décidé qu\'ils n\'attendraient pas le changement. Ils le créeraient.',
    'timeline.donate_life.title': 'Adhésion au club Donate Life',
    'timeline.donate_life.desc': 'Les fondateurs rejoignent le club Donate Life de leur école et découvrent que New York a l\'un des taux d\'inscription de donneurs les plus bas du pays, à seulement 37 %.',
    'timeline.donate_life.detail': 'Les fondateurs ont été choqués de découvrir que le taux d\'inscription de 37 % de New York était parmi les plus bas du pays. Ils ont réalisé que le problème n\'était pas que les gens s\'opposaient au don — c\'était que le système rendait trop facile de ne rien dire.',
    'timeline.growing.title': 'Croissance du mouvement',
    'timeline.growing.desc': 'YCOD commence à construire une coalition de jeunes dans tout l\'État de New York, atteignant des centaines de sympathisants.',
    'timeline.growing.detail': 'Le mouvement s\'est étendu au-delà d\'East Aurora. Des étudiants, des enseignants et des membres de la communauté de tout l\'État de New York ont commencé à rejoindre le mouvement. YCOD est passé d\'un club scolaire à une coalition à l\'échelle de l\'État en seulement un an.',
    'timeline.bill_drafted.title': 'Projet de loi A07954',
    'timeline.bill_drafted.desc': 'YCOD rédige et propose une vraie législation — le projet de loi A07954 — pour changer le paramètre par défaut du DMV du consentement explicite au consentement présumé pour le don d\'organes.',
    'timeline.bill_drafted.detail': 'La plupart des groupes étudiants écrivent des lettres. YCOD a écrit une vraie législation. Le projet de loi A07954 proposait de changer le paramètre par défaut du DMV du consentement explicite au consentement présumé — un simple changement comportemental soutenu par des décennies de recherche.',
    'timeline.partnerships.title': 'Expansion des partenariats',
    'timeline.partnerships.desc': 'Des partenariats clés sont formés avec WaitList Zero, ONE8FIFTY, la Fondation Chris Klug, la Croix-Rouge américaine de WNY et le Conseil des Églises de l\'État de New York.',
    'timeline.partnerships.detail': 'YCOD s\'est associé à WaitList Zero, ONE8FIFTY, la Fondation Chris Klug, la Croix-Rouge américaine de WNY et le Conseil des Églises de l\'État de New York — construisant une coalition qui couvre la santé, la foi et le sport.',
    'timeline.red_cross.title': 'Nomination Croix-Rouge',
    'timeline.red_cross.desc': 'YCOD est nominé pour le prix Vrais Héros de l\'Éducation de la Croix-Rouge américaine. Une législation mise à jour est préparée.',
    'timeline.red_cross.detail': 'La reconnaissance de la Croix-Rouge américaine a validé ce que l\'équipe savait déjà : les jeunes peuvent impulser de vrais changements politiques. La nomination a attiré l\'attention nationale sur l\'approche législative de YCOD.',
    'timeline.tedx.title': 'Conférence TEDx',
    'timeline.tedx.desc': 'Evan Roden présente une conférence TEDx sur l\'engagement politique des jeunes et le don d\'organes, touchant des milliers de spectateurs.',
    'timeline.tedx.detail': 'Evan est monté sur la scène TEDx pour démontrer que les jeunes ne sont pas apolitiques — ils sont plus engagés que jamais. La conférence a relié la défense du don d\'organes à l\'histoire plus large de l\'engagement civique des jeunes.',
    'timeline.members_3000.title': '3 000+ membres',
    'timeline.members_3000.desc': 'Le mouvement s\'étend à plus de 3 000 membres des États-Unis et du monde entier.',
    'timeline.members_3000.detail': 'De quatre étudiants dans une école à plus de 3 000 membres dans plusieurs pays. YCOD a prouvé que la défense du don d\'organes résonne au-delà des frontières, des cultures et des générations.',
    'timeline.ny_50.title': 'NY dépasse 50 %',
    'timeline.ny_50.desc': 'Un moment historique : l\'État de New York dépasse 50 % d\'inscription au don d\'organes pour la première fois en octobre 2024.',
    'timeline.ny_50.detail': 'Après des années de plaidoyer, New York a enfin franchi le seuil de 50 % d\'inscription. C\'est un progrès — mais avec des États comme l\'Alaska à plus de 90 %, il reste encore du travail à faire.',


