    'about.impact.title': 'Notre Impact en Chiffres',
    'about.impact.subtitle': 'De quatre élèves dans une école à un mouvement à l\'échelle mondiale.',
    'about.impact.members': 'Membres dans le Monde',
    'about.impact.schools': 'Écoles Touchées',
    'about.impact.states': 'États Représentés',
    'about.impact.countries': 'Pays Touchés',
    'about.impact.presentations': 'Présentations Réalisées',
    'about.impact.registered': 'Donneurs Inscrits',
